package com.ias.approval;

import org.junit.jupiter.api.Test;
import org.h2.jdbcx.JdbcDataSource;
import org.h2.tools.RunScript;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.ias.approval.FeeApproval.*;

/** H2/connection fault evidence only, not actual MySQL/HTTP/owner coverage acceptance. */
class FeeApprovalStoreTest {
    final FeeApprovalTest fixture=new FeeApprovalTest();
    final Actor applicant=new Actor(1,2),supervisor=new Actor(1,4);
    JdbcDataSource database()throws Exception{return new ApprovalJdbcTest().database();}
    class Authority implements FeeApprovalStore.Authority {
        boolean allowed=true;boolean current=true;boolean ack=true;Confirmation confirmation;
        public Facts verify(Connection c,Actor a,Command cmd,Application app){return new Facts(cmd.basis(),confirmation,current,ack,allowed,true,true,true,true);}
        public void read(Connection c,Actor a,Application app){if(!allowed)throw new ApprovalFailure(403,"CURRENT_SCOPE_REVOKED");}
    }
    FeeApprovalStore store(JdbcDataSource d,Authority a){return new FeeApprovalStore(d,a,Clock.systemUTC());}
    long count(JdbcDataSource d,String table)throws Exception{try(var c=d.getConnection();var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getLong(1);}}
    Command submit(Basis b){return fixture.command(UUID.randomUUID(),Action.SUBMIT,0,b);}
    @Test void defaultAuthorityFailsBeforeAnyApplicationOrReceipt()throws Exception{var d=database();assertEquals(503,assertThrows(ApprovalFailure.class,()->new FeeApprovalStore(d).execute(applicant,submit(fixture.basis(false,false)))).status());assertEquals(0,count(d,"fee_approval_application"));assertEquals(0,count(d,"approval_finance_generation"));}
    @Test void persistsFourFactsAndExactReplayReturnsHistoricalReceiptAfterDecision()throws Exception{var d=database();var a=new Authority();var s=store(d,a);var cmd=submit(fixture.basis(false,false));var first=s.execute(applicant,cmd);var done=s.execute(supervisor,fixture.command(first.id(),Action.APPROVE,1,cmd.basis()));assertEquals(State.COMPLETED,done.state());assertEquals(first,s.execute(applicant,cmd));assertEquals(first,s.query(applicant,cmd.operationId()));assertEquals(done,s.detail(applicant,first.id()));for(String t:List.of("fee_approval_operation","fee_approval_audit","fee_approval_outbox"))assertEquals(2,count(d,t));assertEquals(1,count(d,"fee_approval_application"));}
    @Test void replayAndQueryRecheckCurrentPermission()throws Exception{var d=database();var a=new Authority();var s=store(d,a);var cmd=submit(fixture.basis(false,false));s.execute(applicant,cmd);a.allowed=false;assertEquals(403,assertThrows(ApprovalFailure.class,()->s.execute(applicant,cmd)).status());assertEquals(403,assertThrows(ApprovalFailure.class,()->s.query(applicant,cmd.operationId())).status());assertEquals(404,assertThrows(ApprovalFailure.class,()->s.query(new Actor(1,9),cmd.operationId())).status());assertEquals(404,assertThrows(ApprovalFailure.class,()->s.query(new Actor(2,2),cmd.operationId())).status());}
    @Test void uuidChangedParameterConflictsAndQuoteCannotHaveDuplicateApplication()throws Exception{var d=database();var s=store(d,new Authority());var cmd=submit(fixture.basis(false,false));s.execute(applicant,cmd);assertEquals(409,assertThrows(ApprovalFailure.class,()->s.execute(applicant,new Command(cmd.operationId(),cmd.applicationId(),cmd.action(),cmd.expectedVersion(),cmd.basis(),"changed"))).status());assertEquals(409,assertThrows(ApprovalFailure.class,()->s.execute(applicant,submit(cmd.basis()))).status());assertEquals(1,count(d,"fee_approval_operation"));}
    @Test void auditFailureRollsBackApplicationReceiptAndOutboxThenOriginalUuidRecovers()throws Exception{var d=database();var s=store(d,new Authority());var cmd=submit(fixture.basis(false,false));try(var c=d.getConnection();var q=c.createStatement()){q.execute("ALTER TABLE fee_approval_audit ADD CONSTRAINT qa_fee_audit CHECK(action <> 'SUBMIT')");}assertThrows(ApprovalFailure.class,()->s.execute(applicant,cmd));for(String t:List.of("fee_approval_application","fee_approval_operation","fee_approval_audit","fee_approval_outbox"))assertEquals(0,count(d,t));try(var c=d.getConnection();var q=c.createStatement()){q.execute("ALTER TABLE fee_approval_audit DROP CONSTRAINT qa_fee_audit");}assertEquals(State.PENDING_SUPERVISOR,s.execute(applicant,cmd).state());}
    @Test void fenceRejectsNewDecisionButKnownReceiptStillReads()throws Exception{var d=database();var s=store(d,new Authority());var cmd=submit(fixture.basis(false,false));var app=s.execute(applicant,cmd);try(var c=d.getConnection();var q=c.createStatement()){q.execute("UPDATE approval_finance_generation SET state='FENCED' WHERE tenant_id=1");}assertEquals(409,assertThrows(ApprovalFailure.class,()->s.execute(supervisor,fixture.command(app.id(),Action.APPROVE,1,cmd.basis()))).status());assertEquals(app,s.execute(applicant,cmd));assertEquals(State.WITHDRAWN,s.execute(applicant,fixture.command(app.id(),Action.WITHDRAW,1,cmd.basis())).state());}
    @Test void customerConfirmationIsDurablyBoundBeforeSupervisorAndFinance()throws Exception{var d=database();var a=new Authority();var s=store(d,a);var cmd=submit(fixture.basis(true,true));var app=s.execute(applicant,cmd);assertEquals(State.WAITING_CUSTOMER,app.state());a.confirmation=fixture.confirmation(cmd.basis());app=s.execute(applicant,fixture.command(app.id(),Action.REFRESH,1,cmd.basis()));app=s.execute(supervisor,fixture.command(app.id(),Action.APPROVE,2,cmd.basis()));assertEquals(State.WAITING_FINANCE,app.state());app=s.execute(new Actor(1,5),fixture.command(app.id(),Action.APPROVE,3,cmd.basis()));assertEquals(State.COMPLETED,app.state());assertEquals(a.confirmation,app.confirmation());assertEquals(4,count(d,"fee_approval_audit"));}
    @Test void concurrentDuplicateUsesOneApplicationAndFactSet()throws Exception{var d=database();var s=store(d,new Authority());var cmd=submit(fixture.basis(false,false));try(var pool=Executors.newFixedThreadPool(6)){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Application>>();for(int i=0;i<6;i++)futures.add(pool.submit(()->{start.await();return s.execute(applicant,cmd);}));start.countDown();var first=futures.getFirst().get(15,TimeUnit.SECONDS);for(var f:futures)assertEquals(first,f.get(15,TimeUnit.SECONDS));}for(String t:List.of("fee_approval_application","fee_approval_operation","fee_approval_audit","fee_approval_outbox"))assertEquals(1,count(d,t));}
    @Test void concurrentDifferentDecisionsOneVersionWinner()throws Exception{var d=database();var s=store(d,new Authority());var cmd=submit(fixture.basis(false,false));var app=s.execute(applicant,cmd);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var futures=new ArrayList<Future<Boolean>>();for(Action action:List.of(Action.APPROVE,Action.REJECT))futures.add(pool.submit(()->{start.await();try{s.execute(supervisor,fixture.command(app.id(),action,1,cmd.basis()));return true;}catch(ApprovalFailure e){assertEquals(409,e.status());return false;}}));start.countDown();int wins=0;for(var f:futures)if(f.get(15,TimeUnit.SECONDS))wins++;assertEquals(1,wins);}assertEquals(2,count(d,"fee_approval_operation"));}
    @Test void uncertainCommitNeverRestoresAutocommitOrReusesConnection()throws Exception{var real=database();var c=spy(real.getConnection());var ds=mock(javax.sql.DataSource.class);when(ds.getConnection()).thenReturn(c);doThrow(new SQLException("injected commit lost")).when(c).commit();var s=new FeeApprovalStore(ds,new Authority(),Clock.systemUTC());assertEquals(503,assertThrows(ApprovalFailure.class,()->s.execute(applicant,submit(fixture.basis(false,false)))).status());verify(c,never()).setAutoCommit(true);verify(c,never()).rollback();verify(c).abort(any());assertEquals(503,assertThrows(ApprovalFailure.class,()->s.query(applicant,UUID.randomUUID())).status());verify(ds,times(1)).getConnection();}
    @Test void committedButResponseLostRecoversOriginalReceiptOnFreshConnection()throws Exception{var real=database();var c=spy(real.getConnection());var ds=mock(javax.sql.DataSource.class);when(ds.getConnection()).thenReturn(c);doAnswer(invocation->{invocation.callRealMethod();throw new SQLException("injected post commit lost");}).when(c).commit();var a=new Authority();var s=new FeeApprovalStore(ds,a,Clock.systemUTC());var cmd=submit(fixture.basis(false,false));assertEquals("OPERATION_RESULT_UNKNOWN",assertThrows(ApprovalFailure.class,()->s.execute(applicant,cmd)).getMessage());verify(c,never()).setAutoCommit(true);var fresh=store(real,a);var receipt=fresh.query(applicant,cmd.operationId());assertEquals(receipt,fresh.execute(applicant,cmd));for(String table:List.of("fee_approval_application","fee_approval_operation","fee_approval_audit","fee_approval_outbox"))assertEquals(1,count(real,table));}
    @Test void runtimeRollbackFailureReturnsUnknownInsteadOfOriginalDenialAndQuarantines()throws Exception{var real=database();var c=spy(real.getConnection());var ds=mock(javax.sql.DataSource.class);when(ds.getConnection()).thenReturn(c);doThrow(new SQLException("injected rollback")).when(c).rollback();var a=new Authority();a.allowed=false;var s=new FeeApprovalStore(ds,a,Clock.systemUTC());var failure=assertThrows(ApprovalFailure.class,()->s.execute(applicant,submit(fixture.basis(false,false))));assertEquals(503,failure.status());assertEquals("OPERATION_RESULT_UNKNOWN",failure.getMessage());assertEquals(403,assertInstanceOf(ApprovalFailure.class,failure.getCause()).status());assertEquals(1,failure.getSuppressed().length);verify(c,never()).setAutoCommit(true);verify(c).abort(any());assertEquals(503,assertThrows(ApprovalFailure.class,()->s.query(applicant,UUID.randomUUID())).status());verify(ds,times(1)).getConnection();}
    @Test void sqlRollbackFailureReturnsUnknownAndDiscardsConnection()throws Exception{var real=database();var c=spy(real.getConnection());var ds=mock(javax.sql.DataSource.class);when(ds.getConnection()).thenReturn(c);doThrow(new SQLException("injected statement failure")).when(c).prepareStatement(startsWith("INSERT INTO approval_finance_generation"));doThrow(new SQLException("injected rollback")).when(c).rollback();var s=new FeeApprovalStore(ds,new Authority(),Clock.systemUTC());var failure=assertThrows(ApprovalFailure.class,()->s.execute(applicant,submit(fixture.basis(false,false))));assertEquals(503,failure.status());assertEquals("OPERATION_RESULT_UNKNOWN",failure.getMessage());assertInstanceOf(SQLException.class,failure.getCause());assertEquals(1,failure.getSuppressed().length);verify(c,never()).setAutoCommit(true);verify(c).abort(any());assertEquals(503,assertThrows(ApprovalFailure.class,()->s.query(applicant,UUID.randomUUID())).status());verify(ds,times(1)).getConnection();}
}


